// ---------- merch_create ----------

void test_merch_create(void)
{
	ioopm_merch_t *apple = make_merch("Apple", "Red fruit", 10);

	CU_ASSERT_PTR_NOT_NULL_FATAL(apple);
	CU_ASSERT_STRING_EQUAL(ioopm_merch_get_name(apple), "Apple");
	CU_ASSERT_STRING_EQUAL(ioopm_merch_get_description(apple), "Red fruit");
	CU_ASSERT_EQUAL(ioopm_merch_get_price(apple), 10);

	ioopm_merch_destroy(apple);
}

void test_merch_create_has_empty_storage(void)
{
	ioopm_merch_t *apple = make_merch("Apple", "Red fruit", 10);

	CU_ASSERT_PTR_NOT_NULL_FATAL(ioopm_merch_get_storage_list(apple));
	CU_ASSERT_TRUE(ioopm_list_is_empty(ioopm_merch_get_storage_list(apple)));

	ioopm_merch_destroy(apple);
}

void test_merch_create_twice_gives_separate_merch(void)
{
	ioopm_merch_t *apple = make_merch("Apple", "Red fruit", 10);
	ioopm_merch_t *banana = make_merch("Banana", "Yellow fruit", 20);

	CU_ASSERT_PTR_NOT_EQUAL(apple, banana);
	CU_ASSERT_PTR_NOT_EQUAL(ioopm_merch_get_storage_list(apple), ioopm_merch_get_storage_list(banana));
	CU_ASSERT_STRING_EQUAL(ioopm_merch_get_name(apple), "Apple");
	CU_ASSERT_STRING_EQUAL(ioopm_merch_get_name(banana), "Banana");

	ioopm_merch_destroy(apple);
	ioopm_merch_destroy(banana);
}

