void test_merch_remove_with_stock(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);
	ioopm_merch_t *apple = make_merch("Apple", "Red fruit", 10);
	elem_t result;
	CU_ASSERT_TRUE_FATAL(ioopm_merch_add(&store, apple));
	CU_ASSERT_TRUE_FATAL(ioopm_merch_replenish(&store, "Apple", "A25", 5));

	// The removed merch still carries its storage locations
	CU_ASSERT_TRUE_FATAL(ioopm_merch_remove(&store, "Apple", &result));
	ioopm_merch_t *removed = result.p;
	CU_ASSERT_PTR_NOT_NULL_FATAL(ioopm_merch_get_storage_list(removed));
	CU_ASSERT_EQUAL(ioopm_list_size(ioopm_merch_get_storage_list(removed)), 1);

	ioopm_merch_destroy(removed);
	ioopm_merch_destroy_all(&store);
	ioopm_webstore_destroy(&store);
}

void test_merch_remove_then_add_same_name(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);
	ioopm_merch_t *apple = make_merch("Apple", "Red fruit", 10);
	ioopm_merch_t *new_apple = make_merch("Apple", "Green fruit", 15);
	elem_t result;
	CU_ASSERT_TRUE_FATAL(ioopm_merch_add(&store, apple));
	CU_ASSERT_TRUE_FATAL(ioopm_merch_replenish(&store, "Apple", "A25", 5));

	CU_ASSERT_TRUE_FATAL(ioopm_merch_remove(&store, "Apple", &result));
	CU_ASSERT_TRUE_FATAL(ioopm_merch_add(&store, new_apple));

	// Re-added merch starts over without stock
	CU_ASSERT_EQUAL(ioopm_merch_get_quantity(&store, "Apple"), 0);

	ioopm_merch_destroy(result.p);
	ioopm_merch_destroy_all(&store);
	ioopm_webstore_destroy(&store);
}

