void test_merch_replenish_shelf_occupied_by_another_merch_returns_false(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);
	ioopm_merch_t *apple = make_merch("Apple", "Red fruit", 10);
	ioopm_merch_t *banana = make_merch("Banana", "Yellow fruit", 20);

	CU_ASSERT_TRUE_FATAL(ioopm_merch_add(&store, apple));
	CU_ASSERT_TRUE_FATAL(ioopm_merch_add(&store, banana));
	CU_ASSERT_TRUE_FATAL(ioopm_merch_replenish(&store, "Banana", "B10", 5));

	CU_ASSERT_FALSE(ioopm_merch_replenish(&store, "Apple", "B10", 3));

	// No merch has had its stock changed
	CU_ASSERT_EQUAL(ioopm_merch_get_quantity(&store, "Apple"), 0);
	CU_ASSERT_EQUAL(ioopm_merch_get_quantity(&store, "Banana"), 5);

	// Apple still has no shelves
	CU_ASSERT_TRUE(ioopm_list_is_empty(ioopm_merch_get_stock(&store, "Apple")));

	// B10 still belongs to Banana
	CU_ASSERT_TRUE(ioopm_hash_table_has_key(
		store.storage_ht, string_elem("B10")));

	elem_t owner;
	CU_ASSERT_TRUE_FATAL(ioopm_hash_table_lookup(
		store.storage_ht, string_elem("B10"), &owner));
	CU_ASSERT_STRING_EQUAL(owner.s, "Banana");

	ioopm_merch_destroy_all(&store);
	ioopm_webstore_destroy(&store);
}

