void test_merch_edit_desc_and_price(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);
	ioopm_all_merch_t *ht = store.merch_ht;
	ioopm_merch_t *apple = make_merch("Apple", "Red fruit", 10);
	ioopm_merch_t *edited = make_merch("Apple", "Green fruit", 15);
	elem_t result;
	CU_ASSERT_TRUE_FATAL(ioopm_merch_add(&store, apple));

	if (!ioopm_merch_edit(&store, "Apple", edited))
	{
		ioopm_merch_destroy(edited);
	}
	CU_ASSERT_EQUAL(ioopm_hash_table_size(ht), 1);

	CU_ASSERT_TRUE_FATAL(ioopm_merch_remove(&store, "Apple", &result));
	ioopm_merch_t *removed = result.p;
	CU_ASSERT_STRING_EQUAL(ioopm_merch_get_description(removed), "Green fruit");
	CU_ASSERT_EQUAL(ioopm_merch_get_price(removed), 15);

	ioopm_merch_destroy(removed);
	ioopm_merch_destroy_all(&store);
	ioopm_webstore_destroy(&store);
}

