	CU_ASSERT_TRUE_FATAL(ioopm_merch_add(&store, apple));
	CU_ASSERT_TRUE_FATAL(ioopm_merch_add(&store, banana));

	if (!ioopm_merch_edit(&store, "Apple", edited))
	{
		ioopm_merch_destroy(edited);
	}

	// Names must be unique, so neither merch changes
	CU_ASSERT_EQUAL(ioopm_hash_table_size(ht), 2);
	CU_ASSERT_TRUE_FATAL(ioopm_merch_remove(&store, "Apple", &result));
