	removed = result.p;
	CU_ASSERT_STRING_EQUAL(ioopm_merch_get_description(removed), "Yellow fruit");
	CU_ASSERT_EQUAL(ioopm_merch_get_price(removed), 20);
	ioopm_merch_destroy(removed);

