void test_merch_decrease_stock_partial_amount(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);
	ioopm_merch_t *apple = make_merch("Apple", "Red fruit", 10);

	CU_ASSERT_TRUE_FATAL(ioopm_merch_add(&store, apple));
	CU_ASSERT_TRUE_FATAL(ioopm_merch_replenish(&store, "Apple", "A25", 7));

	CU_ASSERT_TRUE(ioopm_merch_decrease_stock(&store, "Apple", "A25", 3));

	// The quantity has decreased from 7 to 4
	CU_ASSERT_EQUAL(ioopm_merch_get_quantity(&store, "Apple"), 4);

	// The shelf still exists
	ioopm_list_t *stock = ioopm_merch_get_stock(&store, "Apple");
	CU_ASSERT_PTR_NOT_NULL_FATAL(stock);
	CU_ASSERT_EQUAL(ioopm_list_size(stock), 1);

	// The shelf is still in storage_ht
	CU_ASSERT_TRUE(ioopm_hash_table_has_key(
		store.storage_ht, string_elem("A25")));

	ioopm_merch_destroy_all(&store);
	ioopm_webstore_destroy(&store);
}

